    # is a periodic tile to repeat throughout that canvas.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            zeros = []
            while stack:
                y, x = stack.pop()
                zeros.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            # Get the connected color motif adjacent to this zero canvas.
            colors = {}
            frontier = set()
            for y, x in zeros:
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] not in (0, 8):
                        frontier.add((yy, xx))
            for y, x in frontier:
                colors.setdefault(grid[y][x], []).append((y, x))
            if len(colors) != 1 or not frontier:
                continue
            color = next(iter(colors))
            points = colors[color]
            r0, r1 = min(y for y,x in points), max(y for y,x in points)
            c0, c1 = min(x for y,x in points), max(x for y,x in points)
            rh, cw = r1-r0+1, c1-c0+1
            tile = [[grid[y][x] for x in range(c0,c1+1)] for y in range(r0,r1+1)]
            for y, x in zeros:
                out[y][x] = tile[(y-r0) % rh][(x-c0) % cw]
    return out
